ST.xhtml:p:
(*默认双控，单控时请只连接single*)
(*目前不支持部分开保压部分不开和部分用到位信号部分不用的情况*)
RtrigCyl1(CLK := ( bCylAntiRejectionOpen1 OR g_bCylAntiRejectionOpen1 OR g_biCylAntiRejectionOpen1 OR g_bCylAntiRejectionOpen1M));
RtrigCyl0ff1(CLK := (bCylAntiRejectionClose1 OR g_bCylAntiRejectionClose1 OR g_biCylAntiRejectionClose1  OR g_bCylAntiRejectionClose1M ));
IF RtrigCyl1.Q THEN
  IF (g_fCenterClylinder1CoordY-g_fCurrentCoordYBuffer < g_fCenterClylinder1DownDistance) THEN
    IF M.PARAMETER_P[185]=1.0 THEN
		M.ENABLE[185] :=0;
    END_IF;
    g_bCylAntiRejectionOpen1M := FALSE;
    g_bCylAntiRejectionOpen1:=FALSE;
    bCylAntiRejectionOpen1:=FALSE;
    g_bFinishedM185_1:=FALSE;
    g_bAntiRejectionCylClampDone1:=TRUE;
    g_bAntiRejectionCylLoosenDone1:=FALSE;
	bCenter1IsAvoidFlag := TRUE;
  ELSE
	  nTonKeep1(IN :=FALSE);
	  nInPlaceTon1(IN :=FALSE);
	  g_bAntiRejectionCylClampDone1:=FALSE;
	  g_bAntiRejectionCylLoosenDone1:=FALSE;
	  g_bAnitRejectionCylKeepPressuring1:=FALSE;
	  bCylAntiRejectionOpen1:=FALSE;
	  g_bCylAntiRejectionOpen1:=FALSE;
	  bCylAntiRejectionClose1:=FALSE;
	  g_bCylAntiRejectionClose1:=FALSE;
	  bSupportCentercyLinder1DownDoneTimeOutAlarm := FALSE;
	  g_bKeepCenter1DownState := FALSE;
	  g_bCylAntiRejectionOpen1M := FALSE;
      bCenter1IsAvoidFlag := FALSE;
	  IF g_nAntiRejectionCylNum >= 1 THEN
			nCylSwitch1:=10;
	  ELSE
			M.ENABLE[185] :=0;
			g_bFinishedM185_1 := FALSE;
	  END_IF;
  END_IF;
END_IF;

IF RtrigCyl0ff1.Q OR (g_fCenterClylinder1CoordY-g_fCurrentCoordYBuffer < g_fCenterClylinder1DownDistance AND g_boAntiRejectionCylSingleCmd1) THEN

  nTonKeep1(IN :=FALSE);
  nInPlaceTon1(IN :=FALSE);
  g_bAntiRejectionCylClampDone1:=FALSE;
  g_bAntiRejectionCylLoosenDone1:=FALSE;
  g_bAnitRejectionCylKeepPressuring1:=FALSE;
  bCylAntiRejectionOpen1:=FALSE;
  g_bCylAntiRejectionOpen1:=FALSE;
  bCylAntiRejectionClose1:=FALSE;
  g_bCylAntiRejectionClose1:=FALSE;
  bSupportCentercyLinder1UpDoneTimeOutAlarm := FALSE;
  g_bKeepCenter1UpState := FALSE;
  g_bCylAntiRejectionClose1M := FALSE;
  IF g_nAntiRejectionCylNum >= 1 THEN
		nCylSwitch1:=50;
  ELSE
		M.ENABLE[185] :=0;
        g_bFinishedM185_1 := FALSE;
  END_IF;
END_IF;

CASE nCylSwitch1 OF
  0:
    nCylSwitch1:=0;
  10:(*夹紧*)
    g_boAntiRejectionCylSingleCmd1:=TRUE;
    g_boAntiRejectionCylDoubleCmd1:=FALSE; 
    nCylSwitch1:=15;
  15:(*是否使用到位信号*)
    IF bAntiRejectionCyl1IsUseUpPosition THEN(*使用到位信号*)
      nCylSwitch1:=20;
    ELSE
      nCylSwitch1:=30;
    END_IF;
  20:(*使用到位信号，先夹紧到位再判断是否使用保压*)
    IF g_bAntiRejectionCylSingleFB1 THEN
      IF g_bAntiRejectionCylKeepPressure THEN
        nCylSwitch1:=25;
      ELSE
        nCylSwitch1:=0;
        g_bAntiRejectionCylClampDone1:=TRUE;
        bSupportCentercyLinder1UpDoneTimeOutAlarm := FALSE;
        g_bKeepCenter1UpState := TRUE;
        M.ENABLE[185] :=0;
        g_bFinishedM185_1 := FALSE;
        (*夹紧完成*)
      END_IF;
    ELSIF NOT g_bAntiRejectionCylSingleFB1 THEN
      (*夹紧到位超时报警*)
		nInPlaceTon1(IN:=TRUE,PT:=LREAL_TO_TIME(FUN_MSTOS(nCylUpInPlaceDelay1)));
		IF nInPlaceTon1.Q THEN
		  nInPlaceTon1(IN :=FALSE);

		  bSupportCentercyLinder1UpDoneTimeOutAlarm := TRUE;
		END_IF;
    END_IF;



  25:(*保压*)
    nTonKeep1(IN :=TRUE, PT:= LREAL_TO_TIME(FUN_MStoS(nKeepPressureTime)));
    g_bAnitRejectionCylKeepPressuring1:=TRUE;(***)
    IF nTonKeep1.Q THEN
      g_bAnitRejectionCylKeepPressuring1:=FALSE;
      g_boAntiRejectionCylSingleCmd1:=FALSE;
      g_boAntiRejectionCylDoubleCmd1:=FALSE; 
      nTonKeep1(IN :=FALSE);
      nCylSwitch1:=0;
      g_bAntiRejectionCylClampDone1:=TRUE;
      (*夹紧完成*)
    END_IF;
  30:(*不使用到位信号*)
    IF g_bAntiRejectionCylKeepPressure THEN
      nCylSwitch1:=25;
    ELSE
      nCylSwitch1:=35;
    END_IF;
  35:
    nInPlaceTon1(IN:=TRUE,PT:=LREAL_TO_TIME(FUN_MSTOS(nCylUpInPlaceDelay1)));
    IF nInPlaceTon1.Q THEN
      nInPlaceTon1(IN :=FALSE);
      nCylSwitch1:=0;
      g_bAntiRejectionCylClampDone1:=TRUE;
      M.ENABLE[185] :=0;
        g_bFinishedM185_1 := FALSE;
        g_bKeepCenter1UpState := TRUE;
      (*夹紧完成*)
    END_IF;

  50:(*松开*)
    g_boAntiRejectionCylSingleCmd1:=FALSE;
    g_boAntiRejectionCylDoubleCmd1:=TRUE;
    nCylSwitch1:=55;
  55:(*是否使用到位信号*)
    IF bAntiRejectionCyl1IsUseDownPosition THEN(*使用到位信号*)
      nCylSwitch1:=60;
    ELSE
      nCylSwitch1:=70;
    END_IF;
  60:
    IF  g_bAntiRejectionCylDoubleFB1 THEN
      IF g_bAntiRejectionCylKeepPressure THEN
        nCylSwitch1:=65;
      ELSE
        nCylSwitch1:=0;
        g_bAntiRejectionCylLoosenDone1:=TRUE;
        bSupportCentercyLinder1DownDoneTimeOutAlarm := FALSE;
        g_bKeepCenter1DownState := TRUE;
        M.ENABLE[185] :=0;
        g_bFinishedM185_1 := FALSE;
        (*松开完成*)
      END_IF;
    ELSIF NOT g_bAntiRejectionCylDoubleFB1 THEN
       nInPlaceTon1(IN:=TRUE,PT:=LREAL_TO_TIME(FUN_MSTOS(nCylDownInPlaceDelay1)));
		IF nInPlaceTon1.Q THEN
		  nInPlaceTon1(IN :=FALSE);

		  bSupportCentercyLinder1DownDoneTimeOutAlarm:=TRUE;
		  (*松开完成*)
		END_IF;
    END_IF;
  65:
    nTonKeep1(IN :=TRUE, PT:= LREAL_TO_TIME(FUN_MStoS(nKeepPressureTime)));
    g_bAnitRejectionCylKeepPressuring1:=TRUE;(***)
    IF nTonKeep1.Q THEN
      g_bAnitRejectionCylKeepPressuring1:=FALSE;

      g_boAntiRejectionCylSingleCmd1:=FALSE;
      g_boAntiRejectionCylDoubleCmd1:=FALSE; 

      nTonKeep1(IN :=FALSE);
      nCylSwitch1:=0;
      g_bAntiRejectionCylLoosenDone1:=TRUE;
      (*松开完成*)
    END_IF;
  70:(*不使用到位信号*)
    IF g_bAntiRejectionCylKeepPressure THEN
      nCylSwitch1:=65;
    ELSE
      nCylSwitch1:=75;
    END_IF;
  75:
    nInPlaceTon1(IN:=TRUE,PT:=LREAL_TO_TIME(FUN_MSTOS(nCylDownInPlaceDelay1)));
    IF nInPlaceTon1.Q THEN
      nInPlaceTon1(IN :=FALSE);
      nCylSwitch1:=0;
      g_bAntiRejectionCylLoosenDone1:=TRUE;
      M.ENABLE[185] :=0;
        g_bFinishedM185_1 := FALSE;
        g_bKeepCenter1DownState := TRUE;
      (*松开完成*)
    END_IF;
END_CASE;

(*hmi状态灯显示*)
IF bAntiRejectionCyl1IsUseUpPosition THEN(*使用到位信号时，实时拿实际引脚状态反馈*)
  IF g_bAntiRejectionCylSingleFB1 AND g_bKeepCenter1UpState THEN
    nAntiRejectionCylHMI1:=1;
  END_IF;
  IF NOT bSupportCentercyLinderUpNotFilterInPlace1 AND nAntiRejectionCylHMI1 = 1 AND g_bKeepCenter1UpState THEN
    bSupportCentercyLinder1UpDoneTimeOutAlarm:=TRUE;
  ELSIF bSupportCentercyLinderUpNotFilterInPlace1 AND nAntiRejectionCylHMI1 = 1 THEN
    bSupportCentercyLinder1UpDoneTimeOutAlarm:= FALSE;
  END_IF;
ELSE(*不使用到位信号时，那以输出完成状态反馈*)
    IF g_bAntiRejectionCylClampDone1 AND NOT g_bAntiRejectionCylLoosenDone1 AND NOT bCenter1IsAvoidFlag THEN
      nAntiRejectionCylHMI1:=1;
    END_IF;
    bSupportCentercyLinder1UpDoneTimeOutAlarm := FALSE;
END_IF;


(*hmi状态灯显示*)
IF bAntiRejectionCyl1IsUseDownPosition THEN(*使用到位信号时，实时拿实际引脚状态反馈*)
	IF g_bAntiRejectionCylDoubleFB1 AND g_bKeepCenter1DownState THEN
		nAntiRejectionCylHMI1:=2;
	END_IF;
     IF NOT bSupportCentercyLinderDownNotFilterInPlace1 AND nAntiRejectionCylHMI1 = 2 AND g_bKeepCenter1DownState THEN
		bSupportCentercyLinder1DownDoneTimeOutAlarm:=TRUE;
	  ELSIF bSupportCentercyLinderDownNotFilterInPlace1 AND nAntiRejectionCylHMI1 = 2 THEN
		bSupportCentercyLinder1DownDoneTimeOutAlarm:= FALSE;
	  END_IF;
ELSE(*不使用到位信号时，那以输出完成状态反馈*)
	IF (g_bAntiRejectionCylLoosenDone1 AND NOT g_bAntiRejectionCylClampDone1) OR bCenter1IsAvoidFlag THEN
		nAntiRejectionCylHMI1:=2;
    END_IF;
    bSupportCentercyLinder1DownDoneTimeOutAlarm := FALSE;
END_IF;



(*222222222*)
RtrigCyl2(CLK := ( bCylAntiRejectionOpen2 OR g_bCylAntiRejectionOpen2 OR g_biCylAntiRejectionOpen2 OR g_bCylAntiRejectionOpen2M ));
RtrigCyl0ff2(CLK := ( bCylAntiRejectionClose2 OR g_bCylAntiRejectionClose2 OR g_biCylAntiRejectionClose2  OR g_bCylAntiRejectionClose2M ));
IF RtrigCyl2.Q THEN
  IF (g_fCenterClylinder2CoordY-g_fCurrentCoordYBuffer < g_fCenterClylinder2DownDistance) THEN
    IF M.PARAMETER_P[185]=2.0 THEN
		M.ENABLE[185] :=0;
    END_IF;
    g_bCylAntiRejectionOpen2M := FALSE;
    g_bCylAntiRejectionOpen2:=FALSE;
    bCylAntiRejectionOpen2:=FALSE;
    g_bFinishedM185_2:=FALSE;
	  g_bAntiRejectionCylClampDone2:=TRUE;
	  g_bAntiRejectionCylLoosenDone2:=FALSE;
	bCenter2IsAvoidFlag := TRUE;
  ELSE
	  nTonKeep2(IN :=FALSE);
	  nInPlaceTon2(IN :=FALSE);
	  g_bAntiRejectionCylClampDone2:=FALSE;
	  g_bAntiRejectionCylLoosenDone2:=FALSE;
	  g_bAnitRejectionCylKeepPressuring2:=FALSE;
	  bCylAntiRejectionClose2:=FALSE;
	  g_bCylAntiRejectionClose2:=FALSE;
	  bCylAntiRejectionOpen2:=FALSE;
	  g_bCylAntiRejectionOpen2:=FALSE;
	  bSupportCentercyLinder2DownDoneTimeOutAlarm := FALSE;
	  g_bKeepCenter2DownState := FALSE;
	  g_bCylAntiRejectionOpen2M := FALSE;
	  bCenter2IsAvoidFlag := FALSE;
	  IF g_nAntiRejectionCylNum >= 2 THEN
		nCylSwitch2:=10;
	  ELSE
		M.ENABLE[185] :=0;
		g_bFinishedM185_2 := FALSE;
	  END_IF;

  END_IF;
END_IF;

IF RtrigCyl0ff2.Q OR (g_fCenterClylinder2CoordY-g_fCurrentCoordYBuffer < g_fCenterClylinder2DownDistance AND g_boAntiRejectionCylSingleCmd2)  THEN
  nTonKeep2(IN :=FALSE);
  nInPlaceTon2(IN :=FALSE);
  g_bAntiRejectionCylClampDone2:=FALSE;
  g_bAntiRejectionCylLoosenDone2:=FALSE;
  g_bAnitRejectionCylKeepPressuring2:=FALSE;
  bCylAntiRejectionOpen2:=FALSE;
  g_bCylAntiRejectionOpen2:=FALSE;
  bCylAntiRejectionClose2:=FALSE;
  g_bCylAntiRejectionClose2:=FALSE;
  bSupportCentercyLinder2UpDoneTimeOutAlarm := FALSE;
  g_bKeepCenter2UpState := FALSE;
  g_bCylAntiRejectionClose2M := FALSE;
  IF g_nAntiRejectionCylNum >= 2 THEN
	nCylSwitch2:=50;
  ELSE
	M.ENABLE[185] :=0;
	g_bFinishedM185_2 := FALSE;
  END_IF;
END_IF;

CASE nCylSwitch2 OF
  0:
    nCylSwitch2:=0;
  10:(*夹紧*)
    g_boAntiRejectionCylSingleCmd2:=TRUE;
    g_boAntiRejectionCylDoubleCmd2:=FALSE; 
