      g_bAnitRejectionCylKeepPressuring2:=FALSE;
      g_boAntiRejectionCylSingleCmd2:=FALSE;
      g_boAntiRejectionCylDoubleCmd2:=FALSE; 
      nTonKeep2(IN :=FALSE);
