    END_IF;
  35:
    nInPlaceTon2(IN:=TRUE,PT:=LREAL_TO_TIME(FUN_MSTOS(nCylUpInPlaceDelay2)));
    IF nInPlaceTon2.Q THEN
      nInPlaceTon2(IN :=FALSE);
      nCylSwitch2:=0;
      g_bAntiRejectionCylClampDone2:=TRUE;
      bSupportCentercyLinder2UpDoneTimeOutAlarm := FALSE;
      M.ENABLE[185] :=0;
        g_bFinishedM185_2 := FALSE;
      (*夹紧完成*)
    END_IF;

  50:(*松开*)
    g_boAntiRejectionCylSingleCmd2:=FALSE;
    g_boAntiRejectionCylDoubleCmd2:=TRUE;
    nCylSwitch2:=55;
  55:(*是否使用到位信号*)
    IF bAntiRejectionCyl2IsUseDownPosition THEN(*使用到位信号*)
      nCylSwitch2:=60;
    ELSE
      nCylSwitch2:=70;
    END_IF;
  60:
    IF  g_bAntiRejectionCylDoubleFB2 THEN
      IF g_bAntiRejectionCylKeepPressure THEN
        nCylSwitch2:=65;
      ELSE
        nCylSwitch2:=0;
        g_bAntiRejectionCylLoosenDone2:=TRUE;
        bSupportCentercyLinder2DownDoneTimeOutAlarm:=FALSE;
        g_bKeepCenter2DownState := TRUE;
        M.ENABLE[185] :=0;
        g_bFinishedM185_2 := FALSE;
        (*松开完成*)
      END_IF;
    ELSIF NOT g_bAntiRejectionCylDoubleFB2 THEN
       nInPlaceTon2(IN:=TRUE,PT:=LREAL_TO_TIME(FUN_MSTOS(nCylDownInPlaceDelay2)));
		IF nInPlaceTon2.Q THEN
		  nInPlaceTon2(IN :=FALSE);

		  bSupportCentercyLinder2DownDoneTimeOutAlarm:=TRUE;
		  (*松开完成*)
		END_IF;
    END_IF;
  65:
    nTonKeep2(IN :=TRUE, PT:= LREAL_TO_TIME(FUN_MStoS(nKeepPressureTime)));
    g_bAnitRejectionCylKeepPressuring2:=TRUE;(***)
    IF nTonKeep2.Q THEN
      g_bAnitRejectionCylKeepPressuring2:=FALSE;

      g_boAntiRejectionCylSingleCmd2:=FALSE;
      g_boAntiRejectionCylDoubleCmd2:=FALSE; 

      nTonKeep2(IN :=FALSE);
      nCylSwitch2:=0;
