    END_IF;
  75:
    nInPlaceTon2(IN:=TRUE,PT:=LREAL_TO_TIME(FUN_MSTOS(nCylDownInPlaceDelay2)));
    IF nInPlaceTon2.Q THEN
      nInPlaceTon2(IN :=FALSE);
      nCylSwitch2:=0;
      g_bAntiRejectionCylLoosenDone2:=TRUE;
      M.ENABLE[185] :=0;
        g_bFinishedM185_2 := FALSE;
      (*松开完成*)
    END_IF;
END_CASE;

(*hmi状态灯显示*)
IF bAntiRejectionCyl2IsUseUpPosition THEN(*使用到位信号时，实时拿实际引脚状态反馈*)
  IF g_bAntiRejectionCylSingleFB2 AND g_bKeepCenter2UpState  THEN
    nAntiRejectionCylHMI2:=1;
  END_IF;
  IF NOT bSupportCentercyLinderUpNotFilterInPlace2 AND nAntiRejectionCylHMI2 = 1 AND g_bKeepCenter2UpState THEN
    bSupportCentercyLinder2UpDoneTimeOutAlarm:=TRUE;
  ELSIF bSupportCentercyLinderUpNotFilterInPlace2 AND nAntiRejectionCylHMI2 = 1 THEN
    bSupportCentercyLinder2UpDoneTimeOutAlarm:= FALSE;
  END_IF;
ELSE(*不使用到位信号时，那以输出完成状态反馈*)
    IF g_bAntiRejectionCylClampDone2 AND NOT g_bAntiRejectionCylLoosenDone2 AND NOT bCenter2IsAvoidFlag THEN
      nAntiRejectionCylHMI2:=1;
    END_IF;
    bSupportCentercyLinder2UpDoneTimeOutAlarm:=FALSE;
END_IF;


IF bAntiRejectionCyl2IsUseDownPosition THEN(*使用到位信号时，实时拿实际引脚状态反馈*)
	IF g_bAntiRejectionCylDoubleFB2 AND g_bKeepCenter2DownState  THEN
		nAntiRejectionCylHMI2:=2;
	END_IF;
	IF NOT bSupportCentercyLinderDownNotFilterInPlace2 AND nAntiRejectionCylHMI2 = 2 AND g_bKeepCenter2DownState THEN
		bSupportCentercyLinder2DownDoneTimeOutAlarm:=TRUE;
	ELSIF bSupportCentercyLinderDownNotFilterInPlace2 AND nAntiRejectionCylHMI2 = 2 THEN
		bSupportCentercyLinder2DownDoneTimeOutAlarm:= FALSE;
	END_IF;
ELSE(*不使用到位信号时，那以输出完成状态反馈*)
	IF (g_bAntiRejectionCylLoosenDone2 AND NOT g_bAntiRejectionCylClampDone2) OR bCenter2IsAvoidFlag THEN
      nAntiRejectionCylHMI2:=2;
    END_IF;
    bSupportCentercyLinder2DownDoneTimeOutAlarm:=FALSE;
END_IF;
(*3333*)
RtrigCyl3(CLK := ( bCylAntiRejectionOpen3 OR g_bCylAntiRejectionOpen3 OR g_biCylAntiRejectionOpen3 OR g_bCylAntiRejectionOpen3M ));
RtrigCyl0ff3(CLK := ( bCylAntiRejectionClose3 OR g_bCylAntiRejectionClose3 OR g_biCylAntiRejectionClose3  OR g_bCylAntiRejectionClose3M ));
IF RtrigCyl3.Q THEN
  IF (g_fCenterClylinder3CoordY-g_fCurrentCoordYBuffer < g_fCenterClylinder3DownDistance) THEN
    IF M.PARAMETER_P[185]=3.0 THEN
		M.ENABLE[185] :=0;
    END_IF;
    g_bCylAntiRejectionOpen3M := FALSE;
    g_bCylAntiRejectionOpen3:=FALSE;
    bCylAntiRejectionOpen3:=FALSE;
    g_bFinishedM185_3:=FALSE;
	  g_bAntiRejectionCylClampDone3:=TRUE;
	  g_bAntiRejectionCylLoosenDone3:=FALSE;
	  bCenter3IsAvoidFlag := TRUE;
  ELSE
	  nTonKeep3(IN :=FALSE);
	  nInPlaceTon3(IN :=FALSE);
	  g_bAntiRejectionCylClampDone3:=FALSE;
	  g_bAntiRejectionCylLoosenDone3:=FALSE;
	  g_bAnitRejectionCylKeepPressuring3:=FALSE;
	  bCylAntiRejectionOpen3:=FALSE;
	  g_bCylAntiRejectionOpen3:=FALSE;
	  bCylAntiRejectionClose3:=FALSE;
	  g_bCylAntiRejectionClose3:=FALSE;
	  bSupportCentercyLinder3DownDoneTimeOutAlarm:= FALSE;
	  g_bKeepCenter3DownState := FALSE;
	  g_bCylAntiRejectionOpen3M := FALSE;
	  bCenter3IsAvoidFlag := FALSE;
	  IF g_nAntiRejectionCylNum >= 3 THEN
		nCylSwitch3:=10;
	  ELSE
		M.ENABLE[185] :=0;
		g_bFinishedM185_3 := FALSE;
	  END_IF;

  END_IF;
END_IF;

IF RtrigCyl0ff3.Q OR (g_fCenterClylinder3CoordY-g_fCurrentCoordYBuffer < g_fCenterClylinder3DownDistance  AND g_boAntiRejectionCylSingleCmd3) THEN
  nTonKeep3(IN :=FALSE);
  nInPlaceTon3(IN :=FALSE);
  g_bAntiRejectionCylClampDone3:=FALSE;
  g_bAntiRejectionCylLoosenDone3:=FALSE;
  g_bAnitRejectionCylKeepPressuring3:=FALSE;
  bCylAntiRejectionOpen3:=FALSE;
  g_bCylAntiRejectionOpen3:=FALSE;
  bCylAntiRejectionClose3:=FALSE;
  g_bCylAntiRejectionClose3:=FALSE;
  bSupportCentercyLinder3UpDoneTimeOutAlarm:= FALSE;
  g_bKeepCenter3UpState := FALSE;
  g_bCylAntiRejectionClose3M := FALSE;
  IF g_nAntiRejectionCylNum >= 3 THEN
	nCylSwitch3:=50;
  ELSE
	M.ENABLE[185] :=0;
	g_bFinishedM185_3 := FALSE;
  END_IF;
END_IF;

CASE nCylSwitch3 OF
  0:
    nCylSwitch3:=0;
  10:(*夹紧*)
    g_boAntiRejectionCylSingleCmd3:=TRUE;
    g_boAntiRejectionCylDoubleCmd3:=FALSE; 
    nCylSwitch3:=15;
  15:(*是否使用到位信号*)
