        g_bFinishedM185_3 := FALSE;
        (*夹紧完成*)
      END_IF;
    ELSIF NOT g_bAntiRejectionCylSingleFB3 THEN
       nInPlaceTon3(IN:=TRUE,PT:=LREAL_TO_TIME(FUN_MSTOS(nCylUpInPlaceDelay3)));
		IF nInPlaceTon3.Q THEN
		  nInPlaceTon3(IN :=FALSE);

          bSupportCentercyLinder3UpDoneTimeOutAlarm:= TRUE;
		END_IF;
    END_IF;
  25:(*保压*)
    nTonKeep3(IN :=TRUE, PT:= LREAL_TO_TIME(FUN_MStoS(nKeepPressureTime)));
